<template>
  <section class="page">
    <header><div><h1>法律场景工作台</h1><p>结论仅供法律信息参考；未附证据的项目必须人工核验。</p></div><el-button @click="load">刷新任务</el-button></header>
    <el-tabs v-model="mode">
      <el-tab-pane label="合同审查" name="contract_review"><el-upload drag :show-file-list="false" accept=".pdf,.docx" :http-request="uploadContract"><div class="upload-copy">拖拽 PDF/Word 合同到这里，或点击选择文件</div></el-upload><el-input v-model="contractText" type="textarea" :rows="8" placeholder="也可直接粘贴合同正文。" /><el-button type="primary" :loading="submitting" @click="submitContract">开始审查</el-button></el-tab-pane>
      <el-tab-pane label="合规检查" name="compliance_check"><el-select v-model="domain"><el-option label="劳动用工" value="labor"/><el-option label="公司治理" value="company"/></el-select><el-input v-model="complianceText" type="textarea" :rows="8" placeholder="粘贴制度或合同正文"/><el-button type="primary" :loading="submitting" @click="submitCompliance">开始检查</el-button></el-tab-pane>
      <el-tab-pane label="法律文书" name="document_draft"><el-select v-model="template"><el-option v-for="item in templates" :key="item.value" :label="item.label" :value="item.value"/></el-select><el-input v-model="fieldsText" type="textarea" :rows="8" placeholder='填写 JSON，例如 {"applicant":"张三","respondent":"某公司","claims":"支付工资","facts":"拖欠工资"}'/><el-button type="primary" :loading="submitting" @click="submitDocument">生成草稿</el-button></el-tab-pane>
      <el-tab-pane label="维权路径" name="rights_path"><el-radio-group v-model="disputeType"><el-radio-button label="labor">劳动</el-radio-button><el-radio-button label="contract">合同</el-radio-button><el-radio-button label="tort">侵权</el-radio-button></el-radio-group><el-button type="primary" :loading="submitting" @click="submitPath">生成路径</el-button></el-tab-pane>
      <el-tab-pane label="法律报告" name="reports"><p>选择已完成的场景任务下载结构化 PDF 报告。</p></el-tab-pane>
    </el-tabs>
    <el-alert v-if="error" :title="error" type="error" show-icon class="notice"/>
    <el-card class="jobs"><template #header>我的场景任务</template><el-table :data="jobs" @row-click="select"><el-table-column prop="scenario_type" label="场景" width="150"/><el-table-column prop="status" label="状态" width="120"><template #default="{row}"><el-tag :type="statusType(row.status)">{{ row.status }}</el-tag></template></el-table-column><el-table-column label="操作" width="180"><template #default="{row}"><el-button v-if="row.status === 'FAILED'" text @click.stop="retry(row.id)">重试</el-button><el-button v-if="row.status === 'READY'" text type="primary" @click.stop="download(row.id)">下载报告</el-button></template></el-table-column></el-table></el-card>
    <el-card v-if="selected?.result_data" class="result"><template #header>结果 · {{ selected.id }}</template><el-alert :title="selected.result_data.evidence_status === 'verified' ? '已附本次检索并校验的法条引用' : '未取得可验证法条：以下内容需人工核验'" :type="selected.result_data.evidence_status === 'verified' ? 'success' : 'warning'" show-icon/><el-button v-if="selected.scenario_type === 'contract_review'" class="advice-button" :loading="advising" @click="generateAdvice">基于已验证证据生成修改建议</el-button><div v-if="selected.result_data.citations?.length" class="citations"><el-tag v-for="citation in selected.result_data.citations" :key="String(citation)" type="success">{{ citation }}</el-tag></div><el-table v-if="Array.isArray(selected.result_data.findings)" :data="selected.result_data.findings" class="finding-table"><el-table-column prop="clause_position" label="位置" width="90"/><el-table-column prop="risk_type" label="风险类型" width="160"/><el-table-column label="等级" width="90"><template #default="{row}"><el-tag :type="severityType(row.severity)">{{ row.severity }}</el-tag></template></el-table-column><el-table-column prop="reason" label="核验提示"/><el-table-column prop="advice" label="修改建议"/><el-table-column label="引用"><template #default="{row}"><el-tag v-for="citation in row.citations" :key="citation" size="small">{{ citation }}</el-tag><span v-if="!row.citations?.length">需人工核验</span></template></el-table-column></el-table><el-timeline v-else-if="Array.isArray(selected.result_data.path)" class="path"><el-timeline-item v-for="node in selected.result_data.path" :key="node.id || node.stage" :timestamp="node.condition"><strong>{{ node.stage }}</strong>：{{ node.action }}<div>材料：{{ node.materials }}</div></el-timeline-item></el-timeline><el-input v-else-if="selected.result_data.content" :model-value="String(selected.result_data.content)" type="textarea" :rows="12" readonly/><p v-else>任务已完成，下载报告查看完整结果。</p><p class="disclaimer">{{ selected.result_data.disclaimer }}</p></el-card>
  </section>
</template>
<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ElMessage, type UploadRequestOptions } from 'element-plus'
import { scenarioApi, type ScenarioJob } from '@/api/scenarios'
const mode = ref('contract_review'); const contractText = ref(''); const complianceText = ref(''); const domain = ref('labor'); const template = ref('arbitration_application'); const fieldsText = ref(''); const disputeType = ref('labor'); const jobs = ref<ScenarioJob[]>([]); const selected = ref<ScenarioJob>(); const submitting = ref(false); const advising = ref(false); const error = ref('')
const templates = [{value:'complaint',label:'民事起诉状'},{value:'defense',label:'民事答辩状'},{value:'arbitration_application',label:'仲裁申请书'},{value:'lawyer_letter',label:'律师函草稿'},{value:'contract',label:'合同草稿'}]
const statusType = (status: ScenarioJob['status']) => ({READY:'success',FAILED:'danger',PROCESSING:'warning',PENDING:'info'}[status] as 'success' | 'danger' | 'warning' | 'info')
const severityType = (severity: string) => ({high: 'danger', medium: 'warning', low: 'info'}[severity] || 'info') as 'danger' | 'warning' | 'info'
async function load(){ try { jobs.value = await scenarioApi.list() } catch { error.value = '任务加载失败，请确认后端已启动并已登录。' } }
async function submit(type: ScenarioJob['scenario_type'], data: Record<string, unknown>){ submitting.value=true; error.value=''; try { const job=await scenarioApi.create(type,data); ElMessage.success('任务已提交，正在处理'); await load(); await select(job) } catch (e: any) { error.value=e?.response?.data?.detail || '任务提交失败' } finally { submitting.value=false } }
const submitContract=()=>submit('contract_review',{text:contractText.value}); const submitCompliance=()=>submit('compliance_check',{domain:domain.value,text:complianceText.value}); const submitPath=()=>submit('rights_path',{dispute_type:disputeType.value})
async function uploadContract(options: UploadRequestOptions){ submitting.value=true; try { const job=await scenarioApi.uploadContract(options.file); ElMessage.success('合同已解析并提交审查'); await load(); await select(job); options.onSuccess({}) } catch (e:any) { error.value=e?.response?.data?.detail || '合同上传或解析失败'; options.onError(e) } finally { submitting.value=false } }
function submitDocument(){ try { submit('document_draft',{template:template.value,fields:JSON.parse(fieldsText.value)}) } catch { error.value='文书字段必须是合法 JSON。' } }
async function select(job: ScenarioJob){ selected.value=await scenarioApi.get(job.id); if (selected.value.status === 'PENDING' || selected.value.status === 'PROCESSING') window.setTimeout(()=>select(job),800) }
async function retry(id:string){ await scenarioApi.retry(id); await load(); ElMessage.success('任务已重新提交') }
async function generateAdvice(){ if (!selected.value) return; advising.value=true; try { selected.value=await scenarioApi.generateAdvice(selected.value.id); ElMessage.success('已生成修改建议') } catch (e:any) { error.value=e?.response?.data?.detail || '修改建议生成失败' } finally { advising.value=false } }
function download(id:string){ window.open(scenarioApi.reportUrl(id),'_blank','noopener') }
onMounted(load)
</script>
<style scoped>.page{max-width:1240px;margin:0 auto}header{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:20px}h1{margin:0;color:#0f1f3d}p{color:#606266}.el-input,.el-select,.el-radio-group{margin:12px 0;display:block;max-width:900px}.upload-copy{padding:12px;color:#606266}.jobs,.result{margin-top:20px}.notice,.finding-table,.path,.advice-button{margin-top:16px}.citations{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.disclaimer{margin-top:16px;font-size:13px;color:#909399}</style>
